css:
.print-header {
    text-align: center;
    margin-bottom: 15px;
}

.print-header h2 {
    margin: 6px 0;
    font-size: 12px;
    font-weight: bold;
}

.barcode-grid {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
}

.barcode-grid td {
    border: 1px solid #000;
    padding: 8px 4px;
    text-align: center;
    width: 20%;
    font-size: 12px;
    height: 25px;
}
